for phrase in [
    "Step on no pets.",
] {
    let clean: Vec<u8> = phrase
        .bytes()
        .filter(|c| c.is_ascii_alphabetic())
        .map(|c| c.to_ascii_lowercase())
        .collect();
    let yes = clean.iter().eq(clean.iter().rev());
    println!("{} -> {}", phrase, if yes { "yes" } else { "no" });
